import java.util.*;
import java.io.*;

public class Main {
  public static void main(String[] args) throws IOException {
    Scanner sc = new Scanner(System.in);
    PrintWriter pw = new PrintWriter(System.out);
    TaskF task = new TaskF();
    task.solve(1, sc, pw);
    pw.close();
  }

  static class TaskF {
    int n;
    char[] s;
    int[] beauty;

    public void solve(int testNumber, Scanner sc, PrintWriter out) {
      n = sc.nextInt();
      s = sc.next().toCharArray();
      beauty = new int[n];
      int totalBeauty = 0;
      for (int i = 0; i < n; i++) {
        beauty[i] = sc.nextInt();
        totalBeauty += beauty[i];
      }

      List<Integer> equalPairs = new ArrayList<>();
      int[] charCount = new int[128];
      char maxChar = 'a';

      for (int i = 0; i < n / 2; i++) {
        if (s[i] == s[n - 1 - i]) {
          equalPairs.add(i);
          if (++charCount[s[i]] > charCount[maxChar]) {
            maxChar = s[i];
          }
        }
      }

      int answer = totalBeauty;
      for (int idx : equalPairs) {
        answer -= Math.min(beauty[idx], beauty[n - 1 - idx]);
      }

      if (charCount[maxChar] > equalPairs.size() / 2) {
        List<Integer> penalties = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
          if (s[i] != s[n - 1 - i] && s[i] != maxChar && s[n - 1 - i] != maxChar) {
            penalties.add(Math.min(beauty[i], beauty[n - 1 - i]));
          }
        }
        Collections.sort(penalties);
        int rem = 2 * charCount[maxChar] - equalPairs.size();
        for (int i = 0; i < rem; i++) {
          answer -= penalties.get(i);
        }
      }

      out.println(answer);
    }
  }
}
